// Static assets of the machine view (client/static/machine, generated by models/machine/build_model.py),
// and the amber palette read from the brand tokens in app.css.
import type { TargetMap } from "./camera";
import type { HighlightMap } from "./highlights";

export const MACHINE_BASE = "/machine";
export const MODEL_URL = `${MACHINE_BASE}/hyperharbor-machine.glb`;

export interface MachineData {
  targets: TargetMap;
  highlights: HighlightMap;
}

async function json<T>(path: string): Promise<T> {
  const response = await fetch(`${MACHINE_BASE}/${path}`);
  if (!response.ok) throw new Error(`${path}: HTTP ${response.status}`);
  return (await response.json()) as T;
}

export async function loadMachineData(): Promise<MachineData> {
  const [targets, highlights] = await Promise.all([json<TargetMap>("targets.json"), json<HighlightMap>("highlights.json")]);
  return { targets, highlights };
}

/** The exploded still: one outline path per node, in the SVG's own coordinates. */
export interface ExplodedStill {
  viewBox: string;
  parts: { node: string; d: string }[];
}

export function parseExplodedSvg(text: string): ExplodedStill {
  const svg = new DOMParser().parseFromString(text, "image/svg+xml").documentElement;
  if (svg.nodeName !== "svg") throw new Error("exploded.svg is not an SVG document");
  const parts = [...svg.querySelectorAll("g[data-node]")].map((group) => ({
    node: group.getAttribute("data-node") ?? "",
    d: [...group.querySelectorAll("path")].map((path) => path.getAttribute("d") ?? "").join(""),
  }));
  return { viewBox: svg.getAttribute("viewBox") ?? "0 0 1000 800", parts };
}

export async function loadExplodedStill(): Promise<ExplodedStill> {
  const response = await fetch(`${MACHINE_BASE}/exploded.svg`);
  if (!response.ok) throw new Error(`exploded.svg: HTTP ${response.status}`);
  return parseExplodedSvg(await response.text());
}

/** CSS colors of the machine view. */
export interface MachinePalette {
  background: string;
  line: string;
  lineDim: string;
  glow: string;
}

const PALETTE_DEFAULT: MachinePalette = { background: "#0b0d10", line: "#3a4250", lineDim: "#1f252d", glow: "#e39b2e" };

/** Reads --hh-crt-amber-<line|dim|glow> and --hh-crt-screen, falling back to the values above. */
export function readPalette(root: Element | null = typeof document === "undefined" ? null : document.documentElement): MachinePalette {
  const fallback = PALETTE_DEFAULT;
  if (!root) return fallback;
  const style = getComputedStyle(root);
  const token = (property: string, value: string) => style.getPropertyValue(property).trim() || value;
  return {
    background: token("--hh-crt-screen", fallback.background),
    line: token("--hh-crt-amber-line", fallback.line),
    lineDim: token("--hh-crt-amber-dim", fallback.lineDim),
    glow: token("--hh-crt-amber-glow", fallback.glow),
  };
}
